// Focused test of ajustes_farol_diff (farol-26): real ajustes.c, whitelist by
// construction. The argument is an existing, disposable directory. Build with
// function/data sections and linker garbage collection.
//
// "sensivel.h" is generated by tests/farol_ajustes.sh with the REAL
// ajlog_chave_sensivel verdict on every whitelist row: any sensitive key or
// out-of-alphabet token is a "#error" line here — compile-time, per PLANO §5.
#include "sensivel.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define SDL_MAIN_HANDLED
#include "../src/ajustes.c"

static char nomes[64][48], toks[64][48];
static int nums[64], npares;

static void cb(const char *chave, int numero, const char *token, void *ctx) {
  int *n = ctx;
  assert(chave && *n < 64);
  snprintf(nomes[*n], sizeof nomes[0], "%s", chave);
  snprintf(toks[*n], sizeof toks[0], "%s", token ? token : "");
  nums[*n] = numero;
  (*n)++;
}

static int opDeChave(const char *chave) {
  int i;
  for (i = 0; i < AJ_N; i++) if (CHAVE[i] && !strcmp(CHAVE[i], chave)) return i;
  return -1;
}

static int par(const char *nome) {
  int i;
  for (i = 0; i < npares; i++) if (!strcmp(nomes[i], nome)) return i;
  return -1;
}

static int nomeSeguro(const char *s) {
  const char *p;
  for (p = s; *p; p++)
    if (!(*p >= 'a' && *p <= 'z') && !(*p >= '0' && *p <= '9') &&
        *p != '_' && *p != '.' && *p != ':' && *p != '+' && *p != '-')
      return 0;
  return p - s >= 1 && p - s <= 39;
}

static void diffs(void) {
  npares = 0;
  assert(ajustes_farol_diff(cb, &npares) == npares);
}

int main(int argc, char **argv) {
  int i, j, op;
  assert(argc == 2 && strlen(argv[1]) < sizeof dirAjustes);
  setenv("NUVIO_DADOS", argv[1], 1);
  dados_iniciar(argv[1]);
  snprintf(dirAjustes, sizeof dirAjustes, "%s", argv[1]);

  // cb NULL: nada entregue, sem par.
  npares = 0;
  assert(ajustes_farol_diff(NULL, &npares) == 0 && npares == 0);

  // Toda entrada da lista branca resolve numa CHAVE persistida desta build e e
  // escolha ou numero: nem leitura/acao (texto de verdade nunca aparece) nem
  // chave "-" (nao persistida). E nenhuma e sensivel nem tem token largo.
  for (i = 0; i < (int)(sizeof FAROL_AJ_LISTA / sizeof *FAROL_AJ_LISTA); i++) {
    const FarolAjItem *it = &FAROL_AJ_LISTA[i];
    op = opDeChave(it->chave);
    assert(op >= 0 && CHAVE[op][0] != '-');
    assert(OPCOES[op].tipo == OP_ESCOLHA || OPCOES[op].tipo == OP_NUMERO);
    assert(!ajlog_chave_sensivel(CHAVE[op]) && !ajlog_chave_sensivel(it->nome));
    assert(nomeSeguro(it->nome));
    if (it->tipo == FAROL_AJ_ENUM) {
      assert(it->rot && it->n >= nValores(op));
      for (j = 0; j < it->n; j++) assert(nomeSeguro(it->rot[j]));
    }
    if (it->tipo == FAROL_AJ_NUM && it->num) assert(it->n > 0);
    if (it->tipo == FAROL_AJ_BOOL) assert(!it->rot && !it->num);
  }

  // Tudo no padrao de fabrica: zero pares.
  memcpy(valor, valorPadrao, sizeof valor);
  diffs();
  assert(npares == 0);

  // ENUM: indice gravado fora do padrao entrega token e numero.
  op = opDeChave("qualidade");
  assert(op >= 0 && valor[op] == valorPadrao[op]);
  valor[op] = valorPadrao[op] == 2 ? 1 : 2;      // 1080p (ou 4K se 2 for o padrao)
  diffs();
  assert(npares == 1 && par("qualidade_max") == 0);
  assert(nums[0] == valor[op] && !strcmp(toks[0], valor[op] == 2 ? "1080p" : "4k"));
  memcpy(valor, valorPadrao, sizeof valor);

  // ENUM fora da tabela de tokens: vira "outro", nunca texto livre.
  op = opDeChave("playerExternoLocal");
  assert(op >= 0);
  valor[op] = 99;
  diffs();
  assert(npares == 1 && par("player_externo") == 0);
  assert(nums[0] == 99 && !strcmp(toks[0], "outro"));
  memcpy(valor, valorPadrao, sizeof valor);

  // BOOL: o numero e 1/0 pelo indice "Ligado", nao o indice cru.
  op = opDeChave("dvMkvLocal");
  assert(op >= 0);
  valor[op] = valorPadrao[op] == 0 ? 1 : 0;
  diffs();
  assert(npares == 1 && par("dv_mkv") == 0 && nums[0] == (valor[op] == 0 ? 1 : 0) && !toks[0][0]);
  memcpy(valor, valorPadrao, sizeof valor);

  // NUM com tabela: o pacote le o VALOR (GB), nao o indice gravado.
  op = opDeChave("tamanhoMaxLocal");
  assert(op >= 0);
  valor[op] = valorPadrao[op] == 4 ? 5 : 4;      // indice de "8 GB" (ou 15 GB)
  diffs();
  assert(npares == 1 && par("tamanho_max_gb") == 0 && nums[0] == (valor[op] == 4 ? 8 : 15) && !toks[0][0]);
  memcpy(valor, valorPadrao, sizeof valor);

  // NUM sem tabela: o proprio indice gravado.
  op = opDeChave("fonteReporLocal");
  assert(op >= 0);
  valor[op] = valorPadrao[op] == 2 ? 3 : 2;
  diffs();
  assert(npares == 1 && par("fonte_repor") == 0 && nums[0] == valor[op] && !toks[0][0]);
  memcpy(valor, valorPadrao, sizeof valor);

  // Ajuste FORA da lista nunca entrega par, mesmo diferente do padrao.
  op = opDeChave("posterLabelsEnabled");
  assert(op >= 0);
  valor[op] = valorPadrao[op] ? 0 : 1;
  diffs();
  assert(npares == 0);
  memcpy(valor, valorPadrao, sizeof valor);

  // Dois ajustes fora do padrao: dois pares, em ordem da lista.
  valor[opDeChave("dolbyVision")] = valorPadrao[opDeChave("dolbyVision")] ? 0 : 1;
  valor[opDeChave("vidroLocal")] = (valorPadrao[opDeChave("vidroLocal")] + 1) % 3;
  diffs();
  assert(npares == 2 && par("dolby_vision") == 0 && par("glass_ui") == 1);
  assert(nomeSeguro(toks[1]));
  memcpy(valor, valorPadrao, sizeof valor);

  // Tudo emitido obedece o alfabeto do pacote e nunca e sensivel.
  for (op = 0; op < (int)(sizeof FAROL_AJ_LISTA / sizeof *FAROL_AJ_LISTA); op++) {
    int o = opDeChave(FAROL_AJ_LISTA[op].chave);
    assert(o >= 0);
    valor[o] = valorPadrao[o] + 1;
  }
  diffs();
  assert(npares == (int)(sizeof FAROL_AJ_LISTA / sizeof *FAROL_AJ_LISTA));
  for (i = 0; i < npares; i++) {
    assert(nomeSeguro(nomes[i]));
    assert(!ajlog_chave_sensivel(nomes[i]));
    if (toks[i][0]) assert(nomeSeguro(toks[i]));
  }
  memcpy(valor, valorPadrao, sizeof valor);
  diffs();
  assert(npares == 0);

  puts("farol_ajustes: lista branca, diffs enum/num/bool, sem texto nem sensivel");
  return 0;
}
